597:   animate(engine, t) {
598:     // 1. Rotación serena del conjunto orbital (velocidad calmada)
599:     if (engine.anim01_modelGroup) {
600:       engine.anim01_modelGroup.rotation.y = t * 0.12;
601:     }
602: 
603:     // 2. Faro central: rotación propia y respiración de luz
604:     if (engine.anim01_beacon) {
605:       engine.anim01_beacon.rotation.y = t * 0.8;
606:       engine.anim01_beacon.rotation.x = Math.sin(t * 0.6) * 0.15;
607:     }
608:     if (engine.anim01_orbitRing) {
609:       engine.anim01_orbitRing.rotation.z = t * 0.9;
610:     }
611: 
612:     // 3. Levitación orgánica ("breathing effect") con desfase armónico en los 4 Ejes
613:     if (engine.anim01_slabs) {
614:       engine.anim01_slabs.forEach(slab => {
615:         slab.group.position.y = slab.baseY + Math.sin(t * 1.8 + slab.phase) * 0.022;
616:       });
617:     }
