619:     // 4. Trayectoria paramétrica de los pulsos de datos por los enlaces
620:     if (engine.anim01_pulses && engine.anim01_edges) {
621:       const dt = 0.016; // Aproximación estándar de delta frame
622:       engine.anim01_pulses.forEach(p => {
623:         p.userData.progress += dt * 0.42;
624:         if (p.userData.progress > 1.0) p.userData.progress = 0;
625: 
