627:         const tVal = p.userData.progress;
628: 
629:         const pA = edge.from;
630:         const pB = edge.to;
631: 
632:         // Interpolación lineal en X y Z
633:         p.position.x = pA[0] + (pB[0] - pA[0]) * tVal;
634:         p.position.z = pA[2] + (pB[2] - pA[2]) * tVal;
635:         // Elevación en arco parabólico sobre el plano de la maqueta
636:         p.position.y = pA[1] + (pB[1] - pA[1]) * tVal + Math.sin(tVal * Math.PI) * 0.14;
637:       });
638:     }
